function mean(a){var s=0;for(var i=0;i<a.length;i++)s+=a[i];return s/a.length;}
function median(a){var b=a.slice().sort(function(x,y){return x-y;});var n=b.length;if(n%2)return b[(n-1)/2];return (b[n/2-1]+b[n/2])/2;}
function mode(a){var m={},best=0,bestv=[];for(var i=0;i<a.length;i++){var x=a[i];m[x]=(m[x]||0)+1;if(m[x]>best){best=m[x];bestv=[x];}else if(m[x]===best)bestv.push(x);}return bestv;}
function variance(a){var m=mean(a);var s=0;for(var i=0;i<a.length;i++)s+=(a[i]-m)*(a[i]-m);return s/a.length;}
function std(a){return Math.sqrt(variance(a));}
function rangeArr(a){var mn=Math.min.apply(null,a),mx=Math.max.apply(null,a);return mx-mn;}
function quartiles(a){var b=a.slice().sort(function(x,y){return x-y;});var n=b.length;function q(p){var idx=(n-1)*p;var lo=Math.floor(idx),hi=Math.ceil(idx);if(lo===hi)return b[lo];return b[lo]+(b[hi]-b[lo])*(idx-lo);}return {q1:q(0.25),q2:median(b),q3:q(0.75)};}
function describe(a){if(!a.length)return null;return {count:a.length,sum:a.reduce(function(s,x){return s+x;},0),min:Math.min.apply(null,a),max:Math.max.apply(null,a),mean:mean(a),median:median(a),mode:mode(a),variance:variance(a),std:std(a),range:rangeArr(a),quartiles:quartiles(a)};}
var EXPORTS={mean:mean,median:median,mode:mode,variance:variance,std:std,rangeArr:rangeArr,quartiles:quartiles,describe:describe};


